using System.Globalization;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionFramework;
using VisionPluginContracts;
using W=System.Windows.Controls;
using Brush=System.Windows.Media.SolidColorBrush;
using Brushes=System.Windows.Media.Brushes;
namespace VisionPlugins.ImageSource;

public sealed class LightWindow:Window {
 readonly ToolEditorContext context;readonly Dictionary<string,JsonElement> values;readonly W.StackPanel rows=new();bool building,running,continuous,closed;readonly W.Button once=new(){Name="ExecuteLight",Content="执行",Width=66,Height=25,Margin=new Thickness(3,0,0,0)};readonly W.Button loop=new(){Name="ContinuousLight",Content="连续执行",Width=66,Height=25};
 sealed record Choice(string Name,string Value);
 public LightWindow(ToolEditorContext context){this.context=context;values=new LightPlugin().Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());foreach(var p in context.Node.Parameters)values[p.Key]=p.Value.Clone();Width=420;Height=600;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=Color("#F2F3F5");FontFamily=new("Microsoft YaHei UI");FontSize=14;
  foreach(string file in new[]{"Theme.xaml","ListViewComboBoxStyle.xaml","RecScrollBarStyle.xaml","LightControls.xaml"})Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("pack://application:,,,/VisionPlugins.ImageSource;component/Resources/"+file)});
  var comboStyle=new Style(typeof(W.ComboBox),(Style)FindResource("ListViewComboBoxStyle"));comboStyle.Setters.Add(new Setter(W.Control.BackgroundProperty,Brushes.White));Resources.Add(typeof(W.ComboBox),comboStyle);
  var grid=new W.Grid();grid.RowDefinitions.Add(new(){Height=new GridLength(context.Mode==ToolEditorMode.Desktop?34:0)});grid.RowDefinitions.Add(new());grid.RowDefinitions.Add(new(){Height=new GridLength(32)});var title=new W.DockPanel{Background=Color("#242424")};var close=new W.Button{Name="CloseLight",Content="×",Width=44,FontSize=23,Background=Brushes.Transparent,Foreground=Brushes.LightGray,BorderThickness=new Thickness(0)};close.Click+=(_,_)=>Close();W.DockPanel.SetDock(close,W.Dock.Right);title.Children.Add(close);var caption=new W.StackPanel{Orientation=W.Orientation.Horizontal};caption.Children.Add(new W.TextBlock{Text=(context.DisplayIndex is int index?index+" ":"")+context.Node.Name,Foreground=Brushes.White,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(10,0,0,0)});var help=AssetIcon("btn_help.png");help.Margin=new Thickness(16,0,0,0);help.ToolTip="光源";caption.Children.Add(help);title.Children.Add(caption);title.MouseLeftButtonDown+=(_,_)=>DragMove();grid.Children.Add(title);
  var scroll=new W.ScrollViewer{Style=(Style)FindResource("RecScrollViewer"),Content=rows,VerticalScrollBarVisibility=W.ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=W.ScrollBarVisibility.Disabled};rows.Margin=new Thickness(32,18,34,14);W.Grid.SetRow(scroll,1);grid.Children.Add(scroll);
  var commands=new W.StackPanel{Orientation=W.Orientation.Horizontal,HorizontalAlignment=System.Windows.HorizontalAlignment.Right,Margin=new Thickness(0,3,16,3)};loop.Click+=async(_,_)=>{if(continuous){continuous=false;loop.Content="连续执行";return;}if(running)return;continuous=true;loop.Content="停止";do{await Execute();if(continuous&&!closed)await Task.Delay(1);}while(continuous&&!closed);loop.Content="连续执行";once.IsEnabled=true;};once.Click+=async(_,_)=>await Execute();commands.Children.Add(loop);commands.Children.Add(once);var confirm=new W.Button{Name="ConfirmLight",Content="确定",Width=66,Height=25,Margin=new Thickness(3,0,0,0)};confirm.Click+=(_,_)=>Close();commands.Children.Add(confirm);W.Grid.SetRow(commands,2);grid.Children.Add(commands);Closed+=(_,_)=>{closed=true;continuous=false;};Content=new W.Border{BorderBrush=Color("#F34A35"),BorderThickness=new Thickness(0,context.Mode==ToolEditorMode.Desktop?1:0,0,0),Child=grid};Build();
 }
 static Brush Color(string text)=>new((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(text));
 static W.Image AssetIcon(string name)=>new(){Source=new BitmapImage(new Uri("pack://application:,,,/VisionPlugins.ImageSource;component/Resources/"+name)),Width=22,Height=22};
 void Apply()=>context.Apply(values.ToDictionary(p=>p.Key,p=>p.Value.Clone()));
 void Set<T>(string key,T value){values[key]=JsonSerializer.SerializeToElement(value);if(key.EndsWith("LightStateVB",StringComparison.Ordinal))values[key[..^2]]=values[key].Clone();Apply();}
 async Task Execute(){if(running||closed)return;running=true;once.IsEnabled=false;try{await context.Run(values.ToDictionary(p=>p.Key,p=>p.Value.Clone()));}catch(Exception ex){continuous=false;System.Windows.MessageBox.Show(this,ex.Message,"执行失败");}finally{running=false;once.IsEnabled=!continuous;}}
 void Header(string text)=>rows.Children.Add(new W.TextBlock{Text=text,FontWeight=FontWeights.Bold,Margin=new Thickness(0,2,0,12)});
 void Row(string caption,FrameworkElement field){var row=new W.Grid{Height=35};row.ColumnDefinitions.Add(new(){Width=new GridLength(90)});row.ColumnDefinitions.Add(new());row.Children.Add(new W.TextBlock{Text=caption,VerticalAlignment=VerticalAlignment.Center,Foreground=Color("#62676C")});field.VerticalAlignment=VerticalAlignment.Center;W.Grid.SetColumn(field,1);row.Children.Add(field);rows.Children.Add(row);}
 public static string Label(string name)=>name switch{"LightDevice"=>"光源设备","OutputType"=>"输出类型","InputString"=>"触发字符","TriggerTime"=>"触发时间(ms)","InputType"=>"输入类型",_=>ChannelLabel(name)};
 static string ChannelLabel(string name){if(name.Length<9||!char.IsDigit(name[7]))return name;string channel=name[7].ToString();return name[8..] switch{"Enable"=>"通道"+channel+"使能","Brightness" or "BrightnessSub"=>"通道"+channel+"亮度","LightState" or "LightStateVB"=>"光源状态"+channel,"EdgeType"=>"通道"+channel+"沿定义","DurationTime"=>"持续时间(ms)",_=>name};}
 void Build(){building=true;rows.Children.Clear();var device=LightPlugin.Device.Parse(values["LightDevice"].GetString()??"");Header("光源设备");var choices=new[]{new Choice("请选择","")}.Concat((context.Scope?.Service<IAcquisitionLightModuleTransport>()?.Devices??[]).Select(d=>new Choice(d.Name,LightPlugin.DeviceSelection(d)))).ToArray();var picker=new W.ComboBox{Name="LightDevicePicker",ItemsSource=choices,DisplayMemberPath="Name",SelectedValuePath="Value",SelectedValue=values["LightDevice"].GetString(),Height=29};if(picker.SelectedIndex<0)picker.SelectedIndex=0;picker.SelectionChanged+=(_,_)=>{if(building||picker.SelectedItem is not Choice choice)return;values["LightDevice"]=JsonSerializer.SerializeToElement(choice.Value);if(choice.Value.Length>0)for(int i=1;i<=8;i++){values[$"Channel{i}Enable"]=JsonSerializer.SerializeToElement(false);values[$"Channel{i}LightState"]=JsonSerializer.SerializeToElement(1);values[$"Channel{i}EdgeType"]=JsonSerializer.SerializeToElement(1);values[$"Channel{i}DurationTime"]=JsonSerializer.SerializeToElement(0);}values["Channel1LightStateVB"]=JsonSerializer.SerializeToElement(1);values["Channel2LightStateVB"]=JsonSerializer.SerializeToElement(1);for(int i=1;i<=6;i++)context.SetInputInteger?.Invoke($"InputChannel{i}Brightness",null);Apply();Build();};var panel=new W.DockPanel();var setup=new W.Button{Name="ConfigureLightResources",Content=AssetIcon("ic_modal_视觉控制器_normal.png"),Width=28,Background=Brushes.Transparent,BorderThickness=new Thickness(0),IsEnabled=context.ConfigureLights is not null,ToolTip="光源设备"};W.DockPanel.SetDock(setup,W.Dock.Right);setup.Click+=(_,_)=>{context.ConfigureLights?.Invoke();Build();};panel.Children.Add(setup);panel.Children.Add(picker);Row("光源设备",panel);rows.Children.Add(new W.Border{Height=1,Background=Color("#D7D7D7"),Margin=new Thickness(0,5,0,16)});Header("通道参数");
  foreach(var field in LightUiRules.Fields(device.Type).Where(f=>f.Visible&&f.Name!="LightDevice")){
   string key=field.Name;switch(field.Kind){
    case "Boolean":var toggle=new W.Primitives.ToggleButton{Name=key,Style=(Style)FindResource("LightSwitch"),IsChecked=values[key].GetBoolean()};toggle.Checked+=(_,_)=>{if(!building)Set(key,true);};toggle.Unchecked+=(_,_)=>{if(!building)Set(key,false);};Row(Label(key),toggle);break;
    case "Integer":var numeric=new AcquisitionNumericControl{Name=key,Minimum=field.Minimum,Maximum=field.Maximum,Integer=true,Text=values[key].GetInt32().ToString(CultureInfo.InvariantCulture),Foreground=Color("#62676C")};numeric.ValueChanged+=value=>{if(building)return;if(key.EndsWith("Brightness",StringComparison.Ordinal)&&value>LightPlugin.BrightnessMaximum(device.Type)){Build();return;}Set(key,(int)value);};FrameworkElement number=numeric;if(key=="TriggerTime"||key.EndsWith("DurationTime",StringComparison.Ordinal)){var linked=new W.DockPanel();var link=LinkButton(key,true,DataKind.Integer);W.DockPanel.SetDock(link,W.Dock.Right);linked.Children.Add(link);linked.Children.Add(numeric);number=linked;}Row(Label(key),number);break;
    case "Enumeration":var options=key=="OutputType"?new[]{"OK时输出","NG时输出"}:key.EndsWith("VB",StringComparison.Ordinal)?new[]{"常亮","常灭"}:key.EndsWith("EdgeType",StringComparison.Ordinal)?new[]{"上升沿","下降沿"}:new[]{"触发后亮（常灭）","触发后灭（常亮）"};var combo=new W.ComboBox{Name=key,ItemsSource=options,SelectedIndex=values[key].GetInt32()-1,Height=29};combo.SelectionChanged+=(_,_)=>{if(!building&&combo.SelectedIndex>=0)Set(key,combo.SelectedIndex+1);};Row(Label(key),combo);break;
    case "RadioSelecter":var radioRow=new W.StackPanel{Orientation=W.Orientation.Horizontal};for(int i=1;i<=2;i++){int mode=i;var radio=new W.RadioButton{Name="LightInputMode"+i,Style=(Style)FindResource("LightRadio"),Content=i==1?"输入":"订阅",GroupName="LightInputMode",IsChecked=values["InputType"].GetInt32()==i,Margin=new Thickness(0,0,8,0),VerticalAlignment=VerticalAlignment.Center};radio.Checked+=(_,_)=>{if(building)return;Set("InputType",mode);if(mode==1)for(int n=1;n<=6;n++)context.SetInputInteger?.Invoke($"InputChannel{n}Brightness",null);};radioRow.Children.Add(radio);}Row(Label(key),radioRow);break;
    case "ButtonSelecter":string port=key.EndsWith("BrightnessSub",StringComparison.Ordinal)?"Input"+key[..^3]:key;var text=new W.TextBox{Name="Input"+key,Text=context.SubscriptionLabel?.Invoke(port,false)??"",Height=29,Padding=new Thickness(6,0,3,0),VerticalContentAlignment=VerticalAlignment.Center,IsReadOnly=port=="InputString"?context.SetInputText is null:context.SetInputInteger is null,Background=Brushes.Transparent,Foreground=Color("#62676C")};string saved=text.Text;void Commit(){if(text.IsReadOnly||text.Text==saved)return;if(port=="InputString")context.SetInputText?.Invoke(port,text.Text.Length==0?null:text.Text);else if(int.TryParse(text.Text,out int value))context.SetInputInteger?.Invoke(port,value);else if(text.Text.Length==0)context.SetInputInteger?.Invoke(port,null);else text.Text=saved;saved=text.Text;}text.LostKeyboardFocus+=(_,_)=>Commit();text.KeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter)Commit();};var inputPanel=new W.DockPanel();var subscribe=LinkButton(port,false,port=="InputString"?DataKind.Text:DataKind.Integer,()=>{text.Text=context.SubscriptionLabel?.Invoke(port,false)??"";saved=text.Text;});W.DockPanel.SetDock(subscribe,W.Dock.Right);inputPanel.Children.Add(subscribe);inputPanel.Children.Add(text);Row(Label(key),inputPanel);break;
   }
  }building=false;
 }
 W.Button LinkButton(string target,bool parameter,DataKind kind,Action? refresh=null){var link=new W.Button{Name="Subscribe"+target,Content=AssetIcon("ic_btn_link_normal.png"),Width=28,Height=29,Background=Brushes.Transparent,BorderThickness=new Thickness(0),ToolTip=context.SubscriptionLabel?.Invoke(target,parameter) is {Length:>0} label?label:"订阅参数"};link.Click+=(_,_)=>{context.PickSubscription?.Invoke(this,target,parameter,kind);refresh?.Invoke();};return link;}
}
